const target = process.env.MOE_DRILL_TARGET;
const anchors = {
  roster: ['mcp-tool-allowlist.ts', '  "design.read",'],
  handler: ['mcp-dispatch-port.ts', '  "design.read": answerDesignRead,'],
};
export default {
  test: { fileParallelism: false },
  plugins: [{ name: 'design-read-source-deletion-drill', enforce: 'pre',
    transform(code, id) {
      const anchor = anchors[target];
      if (!anchor || !id.replaceAll('\\', '/').endsWith('/' + anchor[0])) return;
      if (code.split(anchor[1]).length !== 2) throw new Error('DRILL_ANCHOR_COUNT_NOT_ONE');
      console.log('DRILL_APPLIED ' + target + ' ' + anchor[0]);
      return { code: code.replace(anchor[1], ''), map: null };
    },
  }],
};

